import math
from itertools import permutations

def get_divisors(m):
    divs = set()
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divs.add(i)
            divs.add(m // i)
    return sorted(list(divs))

def is_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def solve_for_m(m):
    divisors = get_divisors(m)
    n = len(divisors)

    # Necessary condition: the sum of all divisors must be a perfect square.
    sigma_m = sum(divisors)
    if not is_square(sigma_m):
        return False, f"Sigma({m}) = {sigma_m}, not a perfect square."

    # Check all permutations
    for p in permutations(divisors):
        current_sum = 0
        all_squares = True
        for i in range(n):
            current_sum += p[i]
            if not is_square(current_sum):
                all_squares = False
                break

        if all_squares:
            return True, f"Found permutation: {list(p)}"

    return False, "No such permutation found."

# Test m from 2 to 20
results = {}
for m in range(2, 21):
    found, detail = solve_for_m(m)
    results[m] = found

# Output the results
satisfying_m = [m for m, found in results.items() if found]

print(f"Results for m = 2 to 20:")
for m in range(2, 21):
    status = "YES" if results[m] else "NO"
    print(f"m={m}: {status} ({detail.split('(')[-1][:-1]})")

print("\n--- Summary ---")
print(f"Values of m that satisfy the condition: {satisfying_m}")
